import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"Node(TS) · 03 框架与生态","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/nodejs/03-frameworks.md","filePath":"tech-system/backend/nodejs/03-frameworks.md"}'),s={name:"tech-system/backend/nodejs/03-frameworks.md"};function o(i,t,n,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="node-ts-·-03-框架与生态" tabindex="-1">Node(TS) · 03 框架与生态 <a class="header-anchor" href="#node-ts-·-03-框架与生态" aria-label="Permalink to “Node(TS) · 03 框架与生态”">​</a></h1><blockquote><p>Express / Nest / Fastify 等，默认按 <strong>TypeScript</strong> 来写。</p></blockquote><h2 id="_1-express" tabindex="-1">1. Express <a class="header-anchor" href="#_1-express" aria-label="Permalink to “1. Express”">​</a></h2><ul><li>简单直接，中间件模型清晰</li><li>适合 BFF、小 API、Electron 旁路服务</li></ul><p><strong>判断：</strong> 小而美场景的默认选择。生态中间件多，也要自己拼结构（目录、错误处理、校验）。</p><h2 id="_2-fastify" tabindex="-1">2. Fastify <a class="header-anchor" href="#_2-fastify" aria-label="Permalink to “2. Fastify”">​</a></h2><ul><li>更偏性能与 schema 校验</li><li>适合对延迟敏感、仍想保持轻量的服务</li><li>与 JSON schema / TypeBox 结合时，契约感接近 FastAPI</li></ul><h2 id="_3-nestjs" tabindex="-1">3. NestJS <a class="header-anchor" href="#_3-nestjs" aria-label="Permalink to “3. NestJS”">​</a></h2><ul><li>模块、DI、结构像「Spring 味」</li><li>适合 Node 侧也要多人协作、边界清晰的中型后端</li></ul><p><strong>判断：</strong> 真要做中大型 Node 域再上；别小脚本套 Nest（启动与概念成本不值）。</p><p>有 Java Spring 经验时，Nest 的模块/提供者概念好迁移；仍要记住：<strong>运行时是 Node，事务与生态深度不如 Spring + JDBC 熟路。</strong></p><hr><h2 id="_4-实时与配套" tabindex="-1">4. 实时与配套 <a class="header-anchor" href="#_4-实时与配套" aria-label="Permalink to “4. 实时与配套”">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>常见选择</th></tr></thead><tbody><tr><td>WebSocket</td><td><code>ws</code>、Socket.IO（要房间/降级时）</td></tr><tr><td>校验</td><td>zod、class-validator（Nest）</td></tr><tr><td>ORM</td><td>Prisma / TypeORM / 轻封装 SQL——能不用重 ORM 就不用</td></tr><tr><td>日志</td><td>pino / winston；结构化 + request id</td></tr><tr><td>HTTP 客户端</td><td>undici / axios；超时必设</td></tr></tbody></table><hr><h2 id="_5-选择表" tabindex="-1">5. 选择表 <a class="header-anchor" href="#_5-选择表" aria-label="Permalink to “5. 选择表”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>Vue/Electron 配套 API</td><td>Express 或 Fastify</td></tr><tr><td>Node 侧中型业务</td><td>NestJS</td></tr><tr><td>实时</td><td>Socket.IO / <code>ws</code>（按复杂度）</td></tr><tr><td>核心业务数据权威</td><td>仍在 <strong>Java</strong></td></tr></tbody></table><p><strong>原则：</strong> Node 框架为前端与桌面服务；不要在 Node 里复制一整套域规则。</p><p>下一篇：<a href="./04-engineering.html">04 工程实践</a></p>',19)])])}const b=e(s,[["render",o]]);export{_ as __pageData,b as default};
